4.3 Implementação de Paralelismo com Cilk

Paralelismo com a Extensão Cilk.

[columns]
[column=0.5]
#include &lt;stdio.h&gt;
#include &lt;cilk/cilk.h&gt;

static void hello(){
    int i=0;
    for(i=0;i&lt;1000000;i++)
        printf("");
        printf("Hello ");
}

static void world(){
    int i=0;
    for(i=0;i&lt;1000000;i++)
        printf("");
        printf("world! ");
}

int main(){
    cilk_spawn hello();
    cilk_spawn world();
    cilk_sync;
    printf("Done! ");
}
[column=0.5]
#include &lt;stdio.h&gt;
#include &lt;pthread.h&gt;

int main(){
    int sum = 0;
    int i = 0;
    pthread_mutex_t m;
    pthread_mutex_init(&m, NULL);

    cilk_for (i = 0; i &lt;= 1000; i++){
        // lock.
        pthread_mutex_lock(&m);
        sum += i;
        // unlock.
        pthread_mutex_unlock(&m);
    }
    printf("%d\n",sum);
} 
