  n = n + id;
  printf("Thread[%d][%lu]: Valor de n: %d depois.\n", id_omp, id_sys, n);
}

  printf("Thread[%d][%lu]: Valor final de n: %d.\n", omp_get_thread_num(), (long int) pthread_self(), n);
  return 0;
}
